@php($dependents = app(\App\Services\Portal\PortalAccessService::class)->dependents(auth()->user()))
@if($dependents->isNotEmpty())<a class="card dependents-shortcut" href="{{ $dependents->count() === 1 ? route('portal.students.show', $dependents->first()) : route('portal.index') }}"><span class="dependents-count" aria-hidden="true">{{ $dependents->count() }}</span><span><strong>{{ $dependents->count() === 1 ? 'Meu dependente' : 'Meus dependentes' }}</strong><small>{{ $dependents->map(fn ($student) => \Illuminate\Support\Str::of($student->person->social_name ?: $student->person->full_name)->explode(' ')->first())->join(', ', ' e ') }} · abrir o portal</small></span><span class="dependents-go">Abrir →</span></a>@endif
